Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
As behooves any intelligent schoolboy, Kevin Sun is studying psycowlogy, cowculus, and cryptcowgraphy at the Bovinia State University (BGU) under Farmer Ivan. During his Mathematics of Olympiads (MoO) class, Kevin was confronted with a weird functional equation and needs your help. For two fixed integers k and p, where p is an odd prime number, the functional equation states that  for some function . (This equation should hold for any integer x in the range 0 to p - 1, inclusive.)It turns out that f can actually be many different functions. Instead of finding a solution, Kevin wants you to count the number of distinct functions f that satisfy this equation. Since the answer may be very large, you should print your result modulo 109 + 7.
</problem_description>

Here is the GNU C++ code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <climits>
#include <cctype>
#include <iomanip>
#include <queue>
#include <stack>
#include <set>
#include <map>
#include <cassert>
using namespace std;

using i64 = long long;
using u64 = unsigned long long;
using f80 = long double;
using pii = pair<int, int>;
using vi = vector<int>;
using vii = vector<pii>;
using pll = pair<i64, i64>;

const int MOD = 1000000007;
const int INF = 1000000000;
const i64 LINF = 1000000000000000000LL;
const f80 PI = 2 * acos(0.0);
const int MAX_M = 50;
const int MAX_N = 1000007;

i64 binary_exp(i64 base, i64 exponent, i64 modulus) {
    i64 result = 1;
    base %= modulus;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % modulus;
        }
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result;
}

i64 recursive_exp(i64 base, i64 exponent, i64 modulus) {
    if (exponent == 0) {
        return 1 % modulus;
    }
    if (exponent & 1) {
        return (base * recursive_exp(base, exponent - 1, modulus)) % modulus;
    }
    i64 half = recursive_exp(base, exponent >> 1, modulus);
    return (half * half) % modulus;
}

int n, k;
int perm[MAX_N];
bool used[MAX_N];

void run_program() {
    cin >> n >> k;

    if (k == 0) {
        cout << binary_exp(k, k - 1, MOD);
        return;
    }
    if (k == 1) {
        cout << binary_exp(k, k, MOD);
        return;
    }

    for (int i = 0; i < n; ++i) {
        perm[i] = (i64)i * k % n;
    }

    i64 product = 1;
    for (int i = 0; i < n; ++i) {
        if (!used[i]) {
            used[i] = true;
            int current = perm[i];
            int cycle_length = 1;
            while (!used[current]) {
                used[current] = true;
                current = perm[current];
                ++cycle_length;
            }
            if (recursive_exp(k, cycle_length, n) == 1) {
                product = (product * n) % MOD;
            }
        }
    }
    cout << product;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

#ifdef _DEBUG_
    freopen("in.txt", "r", stdin);
#endif

    run_program();

#ifdef _LOCAL_
    // cerr << "Time: " << fixed << setprecision(4) << (double)clock() / CLOCKS_PER_SEC << "s\n";
#endif
    return 0;
}
